; Exact quantization of squared Q8 camera distance, without runtime square root.
; Input A/X/rc2/rc3, output A (0..255). Bank 11 must be selected.
; B000 holds 256 uint32 squared transition distances, generated by prepare_runtime.
.zeropage __rc2,__rc3,__rc4,__rc5,__rc6,__rc7,__rc8,__rc9
.zeropage __rc10,__rc11,__rc12
.section .text.depth_quant,"ax",@progbits
.globl depth_quant
depth_quant:
 sta __rc4
 stx __rc5
 lda __rc2
 sta __rc6
 lda __rc3
 sta __rc7
 lda #128
 sta __rc8
 stz __rc9
1:
 lda __rc8
 ora __rc9
 sta __rc10
 and #63
 asl
 asl
 sta __rc11
 lda __rc10
 lsr
 lsr
 lsr
 lsr
 lsr
 lsr
 ora #$b0
 sta __rc12
 ldy #3
 lda __rc7
 cmp (__rc11),y
 bcc 3f
 bne 2f
 dey
 lda __rc6
 cmp (__rc11),y
 bcc 3f
 bne 2f
 dey
 lda __rc5
 cmp (__rc11),y
 bcc 3f
 bne 2f
 dey
 lda __rc4
 cmp (__rc11),y
 bcc 3f
2:
 lda __rc10
 sta __rc9
3:
 lsr __rc8
 bne 1b
 lda __rc9
 rts
